const data = $input.first().json;
const positions = data.positions || data.trades || data.closedToday || [];
const posList = Array.isArray(positions) ? positions : [];
const today = new Date().toISOString().split("T")[0];
let totalPnl = 0;
let winCount = 0;
let lossCount = 0;
let report = `Daily PnL Report - ${today}\n${=.repeat(40)}\n\n`;
if (posList.length > 0) {
  posList.forEach((p, i) => {
    const pnl = parseFloat(p.pnl || p.profit || p.realizedPnl || 0);
    totalPnl += pnl;
    if (pnl >= 0) winCount++; else lossCount++;
    report += `${i+1}. ${p.symbol || p.pair}: ${p.side || p.direction || "?"} | PnL: $${pnl.toFixed(2)}\n`;
  });
  const winRate = posList.length > 0 ? ((winCount / posList.length) * 100).toFixed(1) : 0;
  report += `\n--- Summary ---\nTotal trades: ${posList.length}\nWins: ${winCount} | Losses: ${lossCount}\nWin rate: ${winRate}%\nTotal PnL: $${totalPnl.toFixed(2)}\n`;
} else {
  report += `No trades recorded today.\nScanner status: ${data.scanner || data.status || "unknown"}\nBalance: ${data.balance || "N/A"}`;
}
return [{json: {report, totalPnl, tradeCount: posList.length}}];
